/**
 * 负责丘比特首夜恋人选择的请求、await 复验、关系绑定、成员归属与事实发布。
 * 输入为原夜上下文和经网关验证的配对；输出是同一关系记录及原事件，数据库存／选择写入由本族槽负责。
 * 原角色、容器、生命与双方 Victory 在等待前后复验；未付选择另拒绝捕获角色的执行退休，纯 current 不附旗。
 * 首关系提交后依次消费选择、安装归属再发布；晚退休不撤销已付关系或截断原完成前缀。
 * 目标阵营按原点捕获并复验当前值，pairCamps仍是提交历史；不将关系／Victory当真实阵营。
 * 同步段不是事务：字段、组件或事件失败保留先完成的前缀，不退款或重新使用旧请求，殉情与判胜另有 owner。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";

import {
  createVictoryComponent,
  type VictoryComponent,
} from "../../../../core/domain/components/victory";
import type { LoversComponent } from "../../../../core/domain/components/lovers";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getCupidState, commitCupidChoice } from "./state-slot";
import { bindLovers, hasCupidNightCommit } from "./relation";

export const CUPID_STAGE: NightStageHandler = {
  id: "cupid",
  priority: 80,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (day !== 1) return;
    if (hasCupidNightCommit(ctx.world, day)) throw new Error("cupid_night_reentry_after_commit");
    for (const actorId of ctx.getAliveByRole(Role.Cupid)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getCupidState(role),
        life = captureNightLife(ctx.world, actorId),
        victory = ctx.world.getComponent(actorId, COMPONENT.Victory);
      if (!state || !life || !victory || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState,
        policy = state.policy,
        affiliations = victory.affiliations,
        membership = JSON.stringify(affiliations);
      const current = () =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.Cupid &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getCupidState(role) === state &&
        state.policy === policy &&
        state.remaining === 1 &&
        state.choice === null &&
        livingNightLife(ctx.world, life) &&
        ctx.world.getComponent(actorId, COMPONENT.Victory) === victory &&
        victory.affiliations === affiliations &&
        JSON.stringify(affiliations) === membership &&
        !hasCupidNightCommit(ctx.world, day);
      // 纯原体当前性保原表达式；新未付准入只消费捕获 Role 的永久拒绝信号。
      const canAct = () => !isRoleExecutionRetired(role);
      if (!current() || !canAct()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current() || !canAct()) break;
        const targets = new Map(
          ctx.world.getAliveEntityIds().map((id) => {
            const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!,
              targetVictory = ctx.world.getComponent(id, COMPONENT.Victory)!;
            return [
              id,
              {
                life: captureNightLife(ctx.world, id)!,
                role: targetRole,
                kind: targetRole.role,
                camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                privateState: targetRole.privateState,
                victory: targetVictory,
                affiliations: targetVictory.affiliations,
                membership: JSON.stringify(targetVictory.affiliations),
              },
            ] as const;
          }),
        );
        if (targets.size < 2) throw new Error("cupid_valid_action_missing");
        const request = ctx.makeRequest(actorId, ["choose_lovers"], {
          stage: "cupid",
          requiresAction: true,
          allow_fallback: false,
          action_failure_policy: "error",
          ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
        });
        if (!current() || !canAct()) break;
        const action = await ctx.actionProvider.getAction(request);
        if (!current() || !canAct()) break;
        if (action?.name !== "choose_lovers") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "choose_lovers" || !canAct()) continue;
        const pairIds: [number, number] = [
          valid.sanitizedCall.args.first_id,
          valid.sanitizedCall.args.second_id,
        ];
        const selected = pairIds.map((id) => targets.get(id));
        if (
          selected.some(
            (target, index) =>
              !target ||
              !livingNightLife(ctx.world, target.life) ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Role) !== target.role ||
              target.role.role !== target.kind ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Camp)?.camp !== target.camp ||
              target.role.privateState !== target.privateState ||
              (target.camp !== Camp.Good && target.camp !== Camp.Wolf) ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Victory) !== target.victory ||
              target.victory.affiliations !== target.affiliations ||
              JSON.stringify(target.affiliations) !== target.membership,
          )
        )
          continue;
        const first = selected[0]!,
          second = selected[1]!,
          mixed = first.camp !== second.camp;
        const record: LoversComponent = Object.freeze({
          actorId,
          day: 1,
          policy,
          pairIds: Object.freeze(pairIds),
          pairCamps: Object.freeze([first.camp, second.camp]) as LoversComponent["pairCamps"],
          groupId: "cupid_lovers",
          mixed,
        });
        const memberIds = new Set(pairIds);
        if (policy === "netease_2017_cupid_follows_lovers_v1") memberIds.add(actorId);
        // 目标／记录 getter 仍先读取；关系 owner 在原 callee／参数求值后、首组件写前检查拒绝尾。
        // 首关系已写后不再消费墓碑：选择付款、归属和事实照原顺序继续，失败保已完成前缀。
        if (!bindLovers(ctx.world, record, [first.life, second.life], canAct)) continue;
        commitCupidChoice(state, pairIds);
        for (const id of memberIds)
          ctx.world.addComponent(
            id,
            COMPONENT.Victory,
            createVictoryComponent([
              mixed
                ? { kind: "relationship", groupId: record.groupId }
                : { kind: "faction", faction: first.camp! },
            ]),
          );
        ctx.events.push({
          timestamp: Date.now(),
          type: "cupid_lovers_chosen",
          payload: { actorId, day: 1, pairIds: [...pairIds] },
        });
        for (const id of pairIds)
          ctx.events.push({
            timestamp: Date.now(),
            type: "lover_recognized",
            payload: { actorId: id, partnerId: pairIds.find((target) => target !== id)! },
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "cupid_relation_resolved",
          payload: record,
        });
        completed = true;
        break;
      }
      if (!completed && current() && canAct()) throw new Error("cupid_valid_action_missing");
    }
  },
};

/**
 * 负责混血儿首夜榜样选择的请求、原体／目标复验及隐藏胜利归属安装。
 * 输入为当前夜上下文和经网关验证的榜样；输出为已选数据、独立归属和原事实，不改变角色或真实阵营。
 * 等待前后仍核原容器、状态、生命和空 Victory；未付准入另拒绝捕获角色的执行退休，纯 current 不附旗。
 * 先构造归属，再在首次数写前拒退休；已消费后按原顺序安装组件和事实，晚退休不退款。
 * 目标阵营按原点捕获并复验真实 Camp 值，安装的是独立Victory归属，不写当前阵营。
 * 同步字段与组件提交失败保留已写前缀；夜提交账本和事件仍在原安装之后，不以玩家知识恢复许可。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";

import {
  createVictoryComponent,
  type VictoryComponent,
} from "../../../../core/domain/components/victory";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { canChooseExemplar, getHybridState, commitHybridChoice } from "./state-slot";

const committed = new WeakMap<World, Set<number>>();
export function hasHybridNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}

export const HYBRID_STAGE: NightStageHandler = {
  id: "hybrid",
  priority: 110,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (day !== 1) return;
    for (const actorId of ctx.getAliveByRole(Role.Hybrid)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!;
      const state = getHybridState(role),
        life = captureNightLife(ctx.world, actorId);
      const victory = ctx.world.getComponent(actorId, COMPONENT.Victory);
      if (!state || !life || !victory || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState,
        affiliations = victory.affiliations;
      const current = () =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.Hybrid &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getHybridState(role) === state &&
        livingNightLife(ctx.world, life) &&
        ctx.world.getComponent(actorId, COMPONENT.Victory) === victory &&
        victory.affiliations === affiliations &&
        affiliations.length === 0 &&
        canChooseExemplar(state, day);
      // 纯原体当前性保原表达式；新未付准入只消费捕获 Role 的永久拒绝信号。
      const canAct = () => !isRoleExecutionRetired(role);
      if (!current() || !canAct()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current() || !canAct()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        if (!targets.size) throw new Error("hybrid_valid_action_missing");
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(actorId, ["choose_exemplar"], {
            stage: "hybrid",
            requiresAction: true,
            allow_fallback: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!current() || !canAct()) break;
        if (action?.name !== "choose_exemplar") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "choose_exemplar" || !canAct()) continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState ||
          (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
        )
          continue;
        const membership = createVictoryComponent([{ kind: "faction", faction: target.camp! }]);
        // 原目标 getter 和归属构造先完成，再准备原提交 callee；参数均是已求值局部。
        // 拒绝尾只在首次库存写前生效；次数已写后的组件／事实失败保原前缀，不退款。
        const commitChoice = commitHybridChoice;
        if (!canAct()) continue;
        commitChoice(state, day, targetId);
        ctx.world.addComponent(actorId, COMPONENT.Victory, membership);
        const days = committed.get(ctx.world) ?? new Set<number>();
        days.add(day);
        committed.set(ctx.world, days);
        ctx.events.push({
          timestamp: Date.now(),
          type: "hybrid_exemplar_chosen",
          payload: { actorId, day, targetId },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "hybrid_affiliation_resolved",
          payload: { actorId, day, targetId, faction: target.camp },
        });
        completed = true;
        break;
      }
      if (!completed && current() && canAct()) throw new Error("hybrid_valid_action_missing");
    }
  },
};

/**
 * 负责狼美人夜间魅惑的请求、等待后原体复验、选择历史、关系绑定及公开／动物私密通知。
 * 输入为原夜上下文与经网关验证的可空目标；输出保留原历史、绑定与事件，拒绝或失效选择不安装新关系。
 * 动物准入与板子识别通过查询端口按原位置调用，通知通过独立事实端口发表，不能将已知数据当作现场权限。
 * 原状态先写历史，再绑定关系、发表 charm_applied，最后按板子追加通知；后续失败不撤销已完成前缀或补发事实。
 * 目标和演员生命版本在原等待前后核对；未付魅惑另拒绝捕获角色的执行退休，不过滤目标或已付关系。
 * 首选择字段写后继续原绑定／事实前缀；本流程不提前领取死亡牵连，实际来源政策、保护与标死另归原 owner。
 */
import { recordCharmSelection } from "./state";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { isRoleExecutionRetired } from "../../../../core/domain/role-execution-authority";
import { Role, Camp, Phase } from "../../../../core/domain/model";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getWolfBeautyState } from "./state";
import { bindCharm } from "./relation";
import { animalBeautyCharmAllowed, isAnimalDreamBoard } from "../animal_dream/beauty-query-ports";
import { appendAnimalBeautyNotice } from "../animal_dream/beauty-fact-ports";

export const WOLF_BEAUTY_CHARM_STAGE: NightStageHandler = {
  id: "wolf_beauty_charm",
  priority: 450,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (!animalBeautyCharmAllowed(ctx.world, day)) return;
    for (const actorId of ctx.getAliveByRole(Role.WolfBeauty)) {
      if (!ctx.isCurrent()) return;
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getWolfBeautyState(role),
        actorLife = ctx.world.getComponent(actorId, COMPONENT.Alive)!,
        actorVersion = aliveLifeVersion(actorLife),
        policy = state?.deathLinkPolicy;
      const canAct = () => !isRoleExecutionRetired(role);
      // 原阵营／槽／本夜库存资格先读取，再拒绝新的未付魅惑；名单本身仍是纯角色数据。
      if (ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf || !state || state.lastActedDay === day || !canAct()) continue;
      const targets = new Map(
        ctx.world
          .getAliveEntityIds()
          .filter((id) => id !== actorId)
          .map((id) => {
            const life = ctx.world.getComponent(id, COMPONENT.Alive)!;
            return [id, { life, version: aliveLifeVersion(life) }] as const;
          }),
      );
      const action = await ctx.actionProvider.getAction(
        ctx.makeRequest(actorId, ["charm"], { stage: "wolf_beauty", requiresAction: false }),
      );
      const current = () =>
        ctx.isCurrent() &&
        animalBeautyCharmAllowed(ctx.world, day) &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.WolfBeauty &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Wolf &&
        getWolfBeautyState(role) === state &&
        state.deathLinkPolicy === policy &&
        state.lastActedDay !== day &&
        ctx.world.getComponent(actorId, COMPONENT.Alive) === actorLife &&
        actorLife.alive &&
        actorVersion !== undefined &&
        aliveLifeVersion(actorLife) === actorVersion;
      if (!current() || !canAct()) continue;
      if (action !== null && action.name !== "charm") continue;
      let targetId = action === null ? null : action.args.target_id;
      if (action) {
        const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !result.ok || result.sanitizedCall?.name !== "charm" || !canAct()) continue;
        targetId = result.sanitizedCall.args.target_id;
      }
      if (targetId !== null) {
        const target = targets.get(targetId);
        if (
          !target ||
          ctx.world.getComponent(targetId, COMPONENT.Alive) !== target.life ||
          !target.life.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.life) !== target.version
        )
          continue;
      }
      // 原 nullable 目标／生命 getter 与提交 callee 先准备；只在首选择写前拒绝。
      // 选择已写即进入原完成段，后续 history／绑定／事实失败或晚退休不退款。
      const recordSelection = recordCharmSelection;
      if (!canAct()) continue;
      recordSelection(state, targetId, day);
      bindCharm(ctx.world, actorId, targetId);
      ctx.events.push({
        timestamp: Date.now(),
        type: "charm_applied",
        payload: { actorId, targetId, day },
      });
      if (isAnimalDreamBoard(ctx.world)) appendAnimalBeautyNotice(ctx.world, ctx.events, day);
    }
  },
};
